    //     <li>"life": "lives"</li>
    //     <li>"elf": "elves"</li>
    //     <li>"loaf": "loaves"</li>
    //     <li>"potato": "potatoes"</li>
    //     <li>"tomato": "tomatoes"</li>
    //     <li>"cactus": "cacti"</li>
    //     <li>"focus": "foci"</li>
