    //     <li>"diagnosis": "diagnoses"</li>
    //     <li>"thesis": "theses"</li>
    //     <li>"criterion": "criteria"</li>
    //     <li>"phenomenon": "phenomena"</li>
    //     <li>"appendix": "appendices"</li>
    //     <li>"index": "indices"</li>
    //     <li>"matrix": "matrices"</li>
    //     <li>"radius": "radii"</li>
    //     <li>"deer": "deer"</li>
    //     <li>"fish": "fish"</li>
    //     <li>"sheep": "sheep"</li>
    //     <li>"swine": "swine"</li>
    //     <li>"moose": "moose"</li>
    //     <li>"goat": "goats"</li>
    //     <li>"ox": "oxen"</li>
    //     <li>"louse": "lice"</li>
    //     <li>"mouse": "mice"</li>
    //     <li>"house": "houses"</li>
    //     <li>"blouse": "blouses"</li>
    //     <li>"scarf": "scarves"</li>
    //     <li>"roof": "roofs"</li>
    //     <li>"chief": "chiefs"</li>
    //     <li>"belief": "beliefs"</li>
    //     <li>"chef": "chefs"</li>
    //     <li>"thief": "thieves"</li>
    //     <li>"cliff": "cliffs"</li>
    //     <li>"proof": "proofs"</li>
    //     <li>"reef": "reefs"</li>
    //     <li>"wolf": "wolves"</li>
    //     <li>"knife": "knives"</li>
    //     <li>"wife": "wives"</li>
    //     <li>"life": "lives"</li>
    //     <li>"elf": "elves"</li>
