isc.defineClass("StringMethod");

// Actual string value of the method is stored in the "value" property

isc.StringMethod.addMethods({

getValue : function () {
    return this.value;
},

// Helper method to get a 'display value' for the stringMethod
// Returns the expression / body of the function or, for actions, the title of the action
getDisplayValue : function () {
    var value = this.getValue();
    if (value == null || isc.isA.String(value)) return value;
    if (value.title != null) return "[" + value.title + "]"
    if (value._constructor == "Process") return "[workflow]";
    // If we were created with a string value, return the raw expression
    return value;

},

// not allowed to have ]]> in a CDATA block
cdata : function (string) {
    var index = string.indexOf("]]>");
    if (index == -1) return "<![CDATA[" + string + "]]>";
    return this.cdata(string.slice(0, index)) + "]]&gt;" + this.cdata(string.slice(index+3));
},

_xmlSerialize : function (name, type, namespace, prefix, refs, path) {
    var value = this.value;
    if (isc.isA.String(value)) {
        return isc.Comm._xmlValue(name, this.cdata(value),
            type || "stringMethod", namespace, prefix);
    } else {
        return isc.StringMethod._xmlSerializeAction(value, name, prefix, refs, path);
    }

}

});


// NOTE: toString functions CANNOT be added by addMethods, because a property named "toString"
// will not be enumerated by for..in.  This is actually part of the ECMAScript standard!

isc.StringMethod.getPrototype().toString = function () {
    var value = this.getValue();
    if (value == null || isc.isA.String(value)) return value;
    return value.toString();
},

isc.StringMethod.addClassMethods({

_$Action:"Action",
// Serialize an action binding (or array of bindings) to XML within an enclosing event tag.
// Arrays arise when Reify's MultiActionPanel stores multiple actions on a single event
// (e.g. recordClick with two target actions).
_xmlSerializeAction : function (action, name, indent, refs, path) {
    // Multiple actions: wrap each individually in the enclosing event tag
    if (isc.isAn.Array(action)) {
        var parts = [isc.Comm._xmlOpenTag(name)];
        for (var i = 0; i < action.length; i++) {
            parts[parts.length] = this._xmlSerializeSingleAction(
                action[i], indent, refs, path);
        }
        parts[parts.length] = "\n";
        parts[parts.length] = indent;
        parts[parts.length] = isc.Comm._xmlCloseTag(name);
        return parts.join(isc.emptyString);
    }

    return this._xmlSerializeSingleAction_wrapped(action, name, indent, refs, path);
},

// Serialize one action binding as XML without an enclosing event tag — used when iterating
// an array of actions that share a single wrapper tag.
_xmlSerializeSingleAction : function (action, indent, refs, path) {
    // Array elements may themselves be StringMethod wrappers (e.g. when
    // convertActions() wrapped each action individually); unwrap to the
    // plain action object so the schema serializes target/name attributes
    // rather than emitting constructor="StringMethod"
    if (isc.isA.StringMethod(action)) action = action.value;

    var schemaName = (action._constructor ? action._constructor : this._$Action),
        schema = isc.DataSource.get(schemaName)
    ;
    // Use the schema name (typically "Action") as the element tag when no schema is available
    if (!schema) {
        return isc.Comm._xmlSerializeObject(schemaName, action, path, refs, indent);
    }
    return schema.xmlSerialize(action, null, indent + "        ", schemaName);
},

// Serialize a single action binding wrapped in an enclosing event tag (the typical case).
_xmlSerializeSingleAction_wrapped : function (action, name, indent, refs, path) {
    if (isc.isA.StringMethod(action)) action = action.value;

    var schemaName = (action._constructor ? action._constructor : this._$Action),
        schema = isc.DataSource.get(schemaName)
    ;
    if (!schema) {
        return isc.Comm._xmlSerializeObject(name, action, path, refs, indent);
    }
    return [isc.Comm._xmlOpenTag(name),
            schema.xmlSerialize(action, null, indent + "        ", schemaName),
            "\n", indent,
            isc.Comm._xmlCloseTag(name)
    ].join(isc.emptyString);
}


})




