isc.defineClass("FieldContainerUtil").addClassProperties({
    _checkInvariants : function (fieldContainer) {
        var allFields = fieldContainer.getAllFields(),
            activeFields = fieldContainer.getActiveFields();

        if (!allFields) {
            // If getAllFields() returns `null`, then either getActiveFields() returns `null`
            // as well, or it is an empty array.
            this._assert(!activeFields || (isc.isAn.Array(activeFields) && activeFields.isEmpty()));
            return;
        }

        this._assert(isc.isAn.Array(allFields));

        var fieldByName = {};
        for (var f = 0; f < allFields.length; ++f) {
            var field = allFields[f];
            // only objects (and specifically exclude String wrapper objects)
            this._assert(!isc.isA.String(field) && isc.isAn.Object(field));
            // no duplicate objects within the list of all fields
            this._assert(allFields.indexOf(field, f + 1) < 0);

            var fieldName = field.name;
            if (fieldName != null) {
                this._assert((isc.isA.CubeGrid && isc.isA.CubeGrid(fieldContainer)) ||
                             String.isValidID(fieldName));
                // Two different field objects cannot have the same name; the `fieldByName` map
                // does not already have an entry for `fieldName`.
                this._assert(!fieldByName[fieldName]);
                fieldByName[fieldName] = field;
            }
        }

        if (!activeFields) {
            return;
        }

        this._assert(isc.isAn.Array(activeFields));

        for (var f = 0; f < activeFields.length; ++f) {
            var field = activeFields[f];
            // only objects
            this._assert(!isc.isA.String(field) && isc.isAn.Object(field));
            // no duplicate objects within the list of active fields
            this._assert(activeFields.indexOf(field, f + 1) < 0);
            // Each active field is within the list of all fields.
            this._assert(allFields.indexOf(field) >= 0);

            var fieldName = field.name;
            if (fieldName != null) {
                this._assert((isc.isA.CubeGrid && isc.isA.CubeGrid(fieldContainer)) ||
                             String.isValidID(fieldName));
                // If a field within the list of active fields has the same name as a field
                // within the list of all fields, then they are the same field object.
                // This assertion is guaranteed to pass at this point, but it's here for clarity.
                this._assert(fieldByName[fieldName] === field);
            }
        }
    },

    _getFieldTitle : function (fieldId, fieldContainer) {
        if (fieldContainer) return fieldContainer.getFieldTitle(fieldId);

        if (fieldId == null) return isc.Class.getInstanceProperty("unknownFieldTitle");
        if (isc.isA.String(fieldId) || !isc.isAn.Object(fieldId)) {
            return String(fieldId);
        }
        var field = fieldId;
        if (isc.isA.String(field.title)) return field.title;
        if (field.name) return field.name;
        return isc.Class.getInstanceProperty("unnamedFieldTitle");
    },

    _getFieldTitleForMessages : function (fieldId, fieldContainer) {
        if (fieldContainer) return fieldContainer.getFieldTitleForMessages(fieldId);

        var title = this._getFieldTitle(fieldId, null);
        if (title != isc.Class.getInstanceProperty("unknownFieldTitle") &&
            title != isc.Class.getInstanceProperty("unnamedFieldTitle") &&
            String.isWhiteSpace(String.htmlStringToString(title)))
        {
            title = "<q>" + title + "</q>";
        }
        return title;
    }
});


//> @interface DynamicFieldContainer
