    // Native event.code to our keyName

    getKeyNameFromCode : function (code) {
        if (code == null || code == "") return "_undefined";

        if (this.eventCode_keyNameMap[code]) return this.eventCode_keyNameMap[code];
        // If we didn't find the code in our map there are a couple of possibilities:
        // - it's an "exotic" key we didn't expect to see, like a media key or an international keyboard key
        // - the event.code value matches our keyName (like "Tab" or "Backspace")
        return code;
    },

