    _getSeleneseKeyName : function (keyName) {
        if (keyName == "Escape")          keyName = "Esc";
        if (keyName.startsWith("Arrow_")) keyName = keyName.substring(6);
        return "${KEY_" + keyName.toUpperCase() + "}";
    },

