    if (isc.EventStream.streams) {
        isc.EventStream.addPageEvent(isc.EventStream.getEventProperties(DOMevent), EH.UNLOAD);
    }

    var result = (isc.Page.handleEvent(null, EH.UNLOAD) != false);


    if (result == true) {
        this.releaseEvents();
    }
    return result;
