    _defaultBigZLayer:"default",

    // getBigZIndex() - used by bringToFront() to determine the target z-index for the
    // canvas in question.
    // The mechanism is this:
    // - by default the "front" of the z-layer is _BIG_Z_INDEX
    // - specific canvii can be marked with a "_zLayerName" that allows them to sit above
    //   the default range, even if bringToFront() is called on some other widget
    //   [_isDragTracker is also used as a shorthand for _zLayerName:"_dragTracker"]
    // - in addition to this, we support changing the "default" layer. This is used in the
    //   "relogin required" flow so the relogin window will float above other elements even
    //   though it doesn't explicitly have its zLayer set

    getBigZIndex : function (layer, dontIncrement) {
        if (layer == null) layer = this._defaultBigZLayer;
        var attr = this._bigZLayers[layer];
        if (attr == null) attr = this._bigZLayers.default;

        if (!dontIncrement) this[attr] += 18;
        return this[attr];
    },

    // Set default the "big z index" layer for all canvii
    // Used by the RPCManager.handleReloginRequired flow
    setDefaultBigZLayer : function (layer) {
        if (this._bigZLayers[layer] == null) {
            this.logWarn("ignoring attempt to set unrecognized big-z-layer:" + layer);
            return;
        }
        this._defaultBigZLayer = layer;
    },

    // This method is invoked by EventHandler.showClickMask()
    // The idea is that if you define a Canvas with zlayerName "notify"
    // it should never be masked by a default clickMask but may be
    // masked by another canvas on the notify layer, or some custom
    // layer with an even higher zIndex like Relogin
    _addUnmaskableCanvii : function (unmaskedCanvases, zLayerName) {

        if (zLayerName == null) zLayerName = "default";
        var bigZ = this.getBigZIndex(zLayerName, true);

        var canvasList = this._topCanvii;

        for (var i = 0; i < canvasList.length; i ++) {

            var canvas = canvasList[i];
            // Nothing to do if the canvas is in the default layer (always bottom of the stack)
            if (canvas == null || canvas._zLayerName == null || canvas._zLayerName == "default") {
                continue;
            }
            var canvasZLayer = canvas._zLayerName;
            if (canvasZLayer == zLayerName) continue;

            var canvasBigZ = this.getBigZIndex(canvasZLayer, true);
            if (canvasBigZ > bigZ) {
                if (unmaskedCanvases.contains(canvas)) {
                    continue;
                }
                unmaskedCanvases.add(canvas);
            }
        }
    },

