//>@classMethod Canvas.startDebuggingOverflow()
// Start to track and report excessive overflow per the supplied settings.
// @param settings (DebugOverflowSettings)
// @see stopDebuggingOverflow()
// @visibility external
//<
startDebuggingOverflow : function (settings) {
    this._debugOverflow = true;

    if (!this._debugOverflowSettings || settings) {
        this._debugOverflowSettings = isc.addProperties({}, this._debugOverflowDefaultSettings,
                                                        settings);
    }
    settings = this._debugOverflowSettings;

    // ensure the debug settings are valid
    var maxSlots = settings.maxTrackedOverflows,
        threshold = settings.selfOverflowThreshold;
    if (threshold > maxSlots) {
        this.logInfo("DebugOverflowSettings validation: Increasing maxTrackedOverflows from " +
                     maxSlots + " to " + threshold + " to match selfOverflowThreshold",
                     "overflow");
        settings.maxTrackedOverflows = threshold;
    }

    this.logDebug("starting to track canvas overflow; excessive overflow will be reported",
                  "overflow");
},

