        if (!active) {
            if (!this.active) {
                this.fireCallback(callback, "success", [true]);
                return;
            }
            this._setActive(false);
            this.fireCallback(callback, "success", [true]);
            return;
        }

        // VA must be enabled before it can be activated - enable() installs
        // key handlers and initializes the speech-recognition engine
        if (!this.enabled) {
            this.logWarn("setActive(true) called but VoiceAssist is not " +
                "enabled - call enable() first");
            this.fireCallback(callback, "success", [false]);
            return;
        }

        // suppress popups during automated testing - VoiceAssist won't work in
        // headless browsers, and Ctrl key events from selection tests can
