// SavedSearchItem retargeted before previous target received an auto-gen'd SSID
_handleItemTargetChanged : function (savedSearchItem, targetComponent) {
    if (this != targetComponent) this.stopSaveSearchesFromItem(savedSearchItem);

},


//> @attr dataBoundComponent.adminSavedSearches (Array of Record : null : IR)
// Locally stored +link{SavedSearches,saved search admin} records that are avaliable to the
