_getFieldGenCC : function () {
    var fieldGenCC = this._fieldGenCC;
    if (!fieldGenCC || (fieldGenCC.canceled && !this.destroyed)) {
        fieldGenCC = this._fieldGenCC = isc.CancellationController.create();
    }
    if (!fieldGenCC.canceled && this.destroyed) fieldGenCC.cancel(this.getID() + " is destroyed.", "system");
    return fieldGenCC;
},

_shouldSkipGeneratingComponent: false,

_shouldSkipGeneratingField : function (field) {
    return !!this._shouldSkipGeneratingComponent;
},

