_editComputedField : function (field, builderType, dynamicProps, builderTitle) {
    // return if FormulaBuilder isn't available
    if (isc.FormulaBuilder == null) return;

    var component = this,
        editMode = !field ? false : true,
        lowercaseBuilderType = builderType.toLowerCase();

    if (isc.isA.String(field)) {
        field = this.getField(field);
    }

    // if the component has fetchFields, we want a testRecord that has all the DS fields,
    // rather than just what's client-side - fetch the full DS record for the
    // current first row and cache it on the grid
    var _this = this;
    if (!this.cacheSampleRecord(null, function (data) {
        // cache the record and call _editComputedField() again
        _this._cachedSampleRecord = data;
        _this._editComputedField(field, builderType, dynamicProps, builderTitle)
        })) {
        return;
    }

    var builder = isc[builderType + "Builder"].create({
        autoDraw: false,
        overflow: "visible",
        component: component, dataSource: component.getDataSource(),
        editMode: editMode, field: field,
        mathFunctions: builderType == "Formula" ?
            isc.MathFunction.getDefaultFunctionNames() : null,
        headerSpans: this.headerSpans,
        showHeaderSpanTitles: this.showHeaderSpanTitlesInFormulaBuilder,
        spanTitleSeparator: this.formulaBuilderSpanTitleSeparator,
        fieldKeyProperties: {
            // star height ensures the grid expands vertically to fill all available
            // space if window is resized, even if there are no more records to show.
            // This looks better than having a bunch of blank space at bottom of window
            height: "*"
        },
        fireOnClose: function(){
            component.userFieldCallback(this, dynamicProps);
        }
    }, this[lowercaseBuilderType + "BuilderProperties"], dynamicProps);


    var fieldTitle = builder.field.title || isc.DataSource.getAutoTitle(builder.field.name);
    this.fieldEditorWindow = this.createAutoChild("fieldEditorWindow", isc.addProperties({}, {
            title: this.fieldEditorWindowTitle.evalDynamicString(this,
                { builderType: builderTitle || builderType, fieldTitle: fieldTitle }),
            items: [builder]
        }, this[lowercaseBuilderType + "EditorProperties"])
    );


    this.fieldEditorWindow.show();
},

cacheSampleRecord : function (value, callback) {
    // we want a testRecord that has all the DS fields, rather than just what's client-side
    if (!this._cachedSampleRecord) {
        // get the first record in the grid
        var record;
        if (value == "firstOpenLeaf" && isc.isA.TreeGrid(this)) {
            var data = this.getData();
            var openList = data.getOpenList(data.getRoot(), isc.Tree.LEAVES_ONLY);
            if (openList.length) record = openList.get(0);
            else record = this.getRecord(0);
        } else { //if (!value || value == "first") {

            if (isc.isA.ListGrid(this)) {
                if (this.fieldPickerShowSampleValues) {
                    var data = this.getOriginalData();
                    record = data && data.getLength() > 0 ? data.get(0) : null;
                }
            } else if (this.showSampleValues) {
                record = this.getRecord(0);
            }
            // ignore e.g. loading markers
            if (!isc.isAn.Object(record)) record = null;
        }

        // get the DS
        var ds = this.getDataSource();

        // if fetchFields is set, we need a server fetch to ensure all the field-values are
        // client-side - otherwise, of if there's no DS at all, return the record if one was
        // detected above, or "first" otherwise
        if (!this.fetchFields || !ds) {
            this._cachedSampleRecord = record ? record : "first";
            return true;
        }

        // if fetchFields is set and there's a DS, get the list of PKs and fetch the full record
        var pks = ds.getPrimaryKeyFieldNames() || [],
            crit = {}
        ;
        pks.map(function(fieldName) { crit[fieldName] = record[fieldName] });

        var _this = this;
        ds.fetchData(crit, function (resp, data) {
            // cache the full testRecord and show the builder, which will use this cached
            // record if it's set
            _this._cachedSampleRecord = data[0];
            _this.delayFireCallback(callback, ["data"], [data[0]]);
        }, { operationId: this.fetchOperation });
        return false;
    }

    return true;
},

