getSummaryFieldValue : function (field, record, summaryFunction) {
    if (!isc.isAn.Object(field)) field = this.getField(field);

    var fieldName = field && field.name,
        fieldIsCacheable = isc.isA.nonemptyString(fieldName),
        cacheObjKey,
        cacheObj;
    if (fieldIsCacheable) {
        if (record && (cacheObj = record[cacheObjKey = "_cache_" + this.getID()]) &&
            this._isCacheInfoCurrent(cacheObj[fieldName]))
        {
            return record[fieldName];
        }
    }

    if (summaryFunction == null) summaryFunction = this.getSummaryFunction(field);
    if (!summaryFunction) return;

    var result = summaryFunction(record, fieldName, this);

    if (fieldIsCacheable &&
        record && !record._noCache)
    {
        record[fieldName] = result;
        if (!cacheObj) cacheObj = record[cacheObjKey] = {};
        this._touchCacheInfo(cacheObj, fieldName);
    }

    return result;
},

