// Returns true if AI is enabled and the common requirements for AI to be used to create
// component views are met.
_supportsAIComponentViews : function (aiServiceMode) {
    if (!(isc.AI && isc.AI.isEnabled())) return false;

    var ds = this.getDataSource();
    if (ds == null || !isc.AI._supportsAIComponentViews(ds, aiServiceMode)) return false;

    // require the length to be known, and for the length to be less than aiMaxRecords

    if (this.data && this.data.getLength) {
        if (this.data.lengthIsKnown && !this.data.lengthIsKnown()) return false;
        if (this.data.getLength() >= this.aiMaxRecords) return false;
    }

    return true;
},

