//> @method dataBoundComponent.isValuePendingAsync()
// Determines whether the value for the given field in the given record is pending asynchronous
// generation in this <code>DataBoundComponent</code>.
// @param record (Record) The record.
// @param field (DBCField) The field.
// @return (Boolean) <code>true</code> if the generation of the value is pending asynchronous
// generation; <code>false</code> otherwise.
// @see DataBoundComponent.isValuePendingAsyncOrAsyncError()
// @visibility AI
//<
isValuePendingAsync : function (record, field) {
    if (!this._shouldSkipGeneratingRecord(record) && this._isFieldGenerated(field)) {
        var asyncObj = this._getAsyncObj(record);
        if (asyncObj) {
            return this._isAsyncInfoCurrent(record, asyncObj[field.name]);
        }
    }

    return false;
},

_isValueAsyncNonSuccess : function (record, field, requireSpecificType, type) {
    // If there is an outstanding request to calculate a value, then any asyncNonSuccess information
    // is no longer applicable, as the state is: we are waiting for the result of the new
    // asynchronous operation.
    if (this.isValuePendingAsync(record, field)) return false;

    if (!this._shouldSkipGeneratingRecord(record) && this._isFieldGenerated(field)) {
        var asyncNonSuccessObj = this._getAsyncNonSuccessObj(record);
        if (asyncNonSuccessObj) {
            var asyncNonSuccessInfo = asyncNonSuccessObj[field.name];
            if (asyncNonSuccessInfo &&
                asyncNonSuccessInfo._cacheOrdinal == this._cacheOrdinal &&
                (!requireSpecificType || asyncNonSuccessInfo._type == type))
            {
                return true;
            }
        }
    }

    return false;
},

//> @method dataBoundComponent.isValueAsyncError()
