_setUserField : function (field, property, value, redrawFunc) {
    if (isc.isA.String(field)) field = this.getField(field);

    // If the formula/summary is not passed (`value` is `undefined`), we need to assume that
    // the field's formula/summary has already been updated, per the documentation of
    // ListGrid.setUserFormula()/setUserSummary().
    var undef;
    if (value === undef) {
        isc.FieldGeneratorUtil._cancelFieldGenerationAndInvalidateCaches(this, field, "The " + property + " of the '" + field.name + "' field is presumed to have been updated.", "application");
    } else {
        isc.FieldGeneratorUtil._beforeSetFieldProperty(this, field, property, value);
        field[property] = value;
    }

    if (property == "userFormula") {
        delete field._generatedFormulaFunc;
        this.rebuildAllFieldsFormulaVarMaps();
    } else {
        delete field._generatedSummaryFunc;
    }

    if (redrawFunc) redrawFunc(field);
},
_setUserFieldText : function (field, property, text, redrawFunc) {
    if (isc.isA.String(field)) field = this.getField(field);

    var undef,
        value = field[property];
    if (value == null) {
        this.logWarn("Cannot set text for " + property + " of field '" + field.name +
                     "' since that user field is null");
        return;
    }

    if (text === undef) {
        value = undef;
    } else {
        value = isc.addPropertiesWithAssign({}, value, {text: text});
    }

    // ListGrid has its own override of _setUserField() with different extra parameters, so
    // we want to make sure that we're calling the DBC version.
    isc.Canvas.getInstanceProperty("_setUserField").call(this, field, property, value, redrawFunc);
},

