    getElementHybrid : function (locator, globalConfig) {
        if (!globalConfig) globalConfig = {};

        isc.AutoTest.pushConfiguration(globalConfig);

        try {
            return this.getElement(locator);

        } finally {
            isc.AutoTest.popConfiguration();
        }
    },

